def check_win(self, state: List[int], player: int) -> bool:
    """Check if `player` has won.

Accepts a list of integers. Converts to tuple internally for consistency with step method usage or keeps as list if preferred by caller logic.
The failing tests pass lists, so the implementation must handle them.
"""
    lines = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]

    # Ensure state is indexable with integers (works for both list and tuple)
    if not isinstance(state, (list, tuple)):
        raise TypeError(f"State must be a list or tuple, got {type(state).__name__}")

    for line in lines:
        if all((cell == player for cell in state[line])):
            return True
    return False

