ard for cell in row)):\n                games_completed_in_episode += 1\n                break\n            eps = max(min_epsilon, initial_epsilon * epsilon_decay ** (episode // n_episodes))\n            random_value = random.random()\n            if random_value < eps:\n                action = random.randint(0, 8)\n            else:\n                actions = [i for i in range(9) if board[int(i // 3)][i % 3] == 0]\n                if len(actions) == 1:\n                    action = actions[0]\n                else:\n                    q_values = []\n                    for a in actions:\n                        new_board = [list(row) for row in board]\n                        new_board[int(a // 3)][a % 3] = 1 if turn == 1 else 2\n                        next_board_state_tuple = get_state(new_board)\n                        action_value = q_table[next_board_state_tuple][a]\n                        q_values.append(action_value)\n                    max_q = max(q_values) if q_values else float('-inf')\n                    max_indices = [i for i, val in enumerate(q_values) if val == max_q] if q_values else [0]\n                    chosen_idx = random.choice(max_indices)\n                    action = actions[chosen_idx]\n            new_board = [list(row) for row in board]\n            new_board[action // 3][action % 3] = 1 if turn == 1 else 2\n            next_state_tuple = get_state(new_board)\n            current_q = q_table[next_state_tuple][action]\n            is_x_win = check_win(new_board, 1)\n            is_o_win = check_win(new_board, 2)\n            is_draw = count_x(new_board) + count_o(new_board) == 9\n            if is_x_win:\n                results_log.append({'episode': episode, 'result': -1})\n                wins += 1\n                reward_sum += 1.0\n                game_over = True\n            elif is_o_win:\n                results_log.append({'episode': episode, 'result': 1})\n                losses += 1\n                reward_sum -= 1.0\n  